function configureHospitality(){
 for(const lang of ['pt','es','en']){
  const h=hospitalityCopy[lang],t=copy[lang];
  for(const k of ['headline','eyebrow','hero','title','desc','cta','servicesTitle','servicesLead'])t[k]=h[k];
  t.services[1]=[...h.menu,'Menu engineering'];
  premiumLabels[lang].hotelCTA=h.cta;
  eventCopy[lang].title=h.eventsTitle;eventCopy[lang].desc=h.eventsDesc;eventCopy[lang].cta=h.eventCTA;
  premiumLabels[lang].quote=h.eventCTA;
 }
}
function hospitalityPaths(lang){const h=hospitalityCopy[lang],urls=['#contact','/destination-weddings/?lang='+lang,'/eventos.html?lang='+lang+'#venues','/eventos.html?lang='+lang+'#planners'];return `<section class="hospitality-paths" aria-label="${h.pathsTitle}"><div class="wrap"><p class="paths-intro">${h.pathsTitle}</p><div class="hospitality-path-grid">${h.paths.map((p,i)=>`<a href="${urls[i]}"><span class="path-index">0${i+1}</span><h2>${p[0]}</h2><p>${p[1]}</p><span class="path-action">${p[2]} <span aria-hidden="true">↗</span></span></a>`).join('')}</div></div></section>`;}
function hospitalityHeroPhoto(lang){const h=hospitalityCopy[lang];return `<figure class="hospitality-hero-photo"><img src="/images/bar-preparation.webp" width="555" height="371" alt="${h.photoCaption}" fetchpriority="high" decoding="async"><figcaption>${h.photoCaption}</figcaption></figure>`;}
function teamSection(lang){const h=hospitalityCopy[lang],s=strategy[lang];return `<section class="section hospitality-team" id="team"><div class="wrap"><span class="eyebrow section-label">${h.teamLabel}</span><div class="section-head"><h2>${h.teamTitle}</h2><p>${h.teamIntro}</p></div><div class="team-grid"><article class="team-member" id="about-rui"><span class="team-monogram" aria-hidden="true">RM</span><div><span class="team-role">${h.ruiRole}</span><h3>Rui Monteiro</h3><p>${s.aboutText}</p><details class="team-detail"><summary>${lang==='pt'?'Percurso & áreas de trabalho':lang==='es'?'Trayectoria & áreas de trabajo':'Background & areas of work'}</summary><p>${s.aboutOps}</p><p>${s.aboutTraining}</p><p class="section-note">${s.aboutNote}</p><ul class="tag-list">${expertise.map(x=>`<li>${x}</li>`).join('')}</ul></details></div></article><article class="team-member"><span class="team-monogram" aria-hidden="true">BA</span><div><span class="team-role">Operations & Events Manager</span><h3>Beatriz Almeida</h3><p>${h.beaBio}</p><ul class="tag-list">${h.beaTags.map(x=>`<li>${x}</li>`).join('')}</ul></div></article></div></div></section>`;}
function partnershipSection(lang){const h=hospitalityCopy[lang];return `<section class="section hospitality-partnerships" id="venues"><div class="wrap split"><div><span class="eyebrow">${h.venueLabel}</span><h2>${h.venueTitle}</h2><p class="wide-lead">${h.venueText}</p><a class="btn" href="https://wa.me/351927653087?text=${encodeURIComponent(h.venueMessage)}" target="_blank" rel="noopener noreferrer">${h.venueCTA} <span aria-hidden="true">↗</span></a></div><div><img class="partner-photo" src="/images/cocktail-service.webp" width="577" height="380" alt="" loading="lazy" decoding="async"><ul class="clean-list">${h.venueItems.map(x=>`<li>${x}</li>`).join('')}</ul></div></div></section><section class="section hospitality-planners" id="planners"><div class="wrap split"><div><span class="eyebrow">${h.plannerLabel}</span><h2>${h.plannerTitle}</h2><p class="wide-lead">${h.plannerText}</p><a class="btn" href="https://wa.me/351927653087?text=${encodeURIComponent(h.plannerMessage)}" target="_blank" rel="noopener noreferrer">${h.plannerCTA} <span aria-hidden="true">↗</span></a></div><div><ul class="clean-list">${h.plannerItems.map(x=>`<li>${x}</li>`).join('')}</ul><p class="planner-contact">Beatriz Almeida<br><span>Operations & Events Manager</span></p></div></div></section>`;}
function hospitalityProcess(lang){const h=hospitalityCopy[lang];return `<section class="section planning-section" id="event-planning"><div class="wrap"><span class="eyebrow">${lang==='pt'?'COMO TRABALHAMOS':lang==='es'?'CÓMO TRABAJAMOS':'HOW WE WORK'}</span><h2>${h.processTitle}</h2><div class="process-grid">${h.process.map((x,i)=>`<article class="step"><span class="step-number">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>`;}
function hospitalityFooter(lang){return `<p class="team-footer">${hospitalityCopy[lang].beaShort}</p>`;}
